[
  {
    "text": "WanSong is a method for generating long-form, commercial-grade songs.",
    "topic": "song generation"
  },
  {
    "text": "Three multimodal generation corpora—JEdit-1M, JMaze-200K, and JNono-200K—have been created for training and evaluation.",
    "topic": "multimodal corpora"
  },
  {
    "text": "StudioRecon's recursive enhancement module with motion-adaptive consistency injection is used to harmonize composed output and reduce artifacts.",
    "topic": "audio enhancement"
  },
  {
    "text": "Two approaches for generating Hindi audio descriptions are explored: (i) directly from English dense video descriptions, and (ii) translating English audio descriptions into Hindi.",
    "topic": "Hindi audio description generation"
  }
]
